<?php
namespace ExcelHerbal\ERP7\Communication;
use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class CommunicationService{
 public static function summary(Actor $a):array{Guard::cap($a,Capabilities::COMM_VIEW);$db=Db::wpdb();$ids=$a->branchIds?implode(',',array_map('intval',$a->branchIds)):'0';return['tasks'=>(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('tasks')." WHERE company_id=%d AND assigned_employee_id=%d AND status='open' ORDER BY due_at IS NULL,due_at,id DESC LIMIT 100",$a->companyId,$a->employeeId),ARRAY_A),'announcements'=>(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('announcements')." WHERE company_id=%d AND status='published' AND (branch_id IS NULL OR branch_id IN ({$ids})) AND (expires_at IS NULL OR expires_at>%s) ORDER BY published_at DESC LIMIT 50",$a->companyId,Db::now()),ARRAY_A),'notifications'=>(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('notifications')." WHERE company_id=%d AND employee_id=%d ORDER BY created_at DESC LIMIT 100",$a->companyId,$a->employeeId),ARRAY_A)];}
 public static function completeTask(Actor $a,int $id):array{Guard::cap($a,Capabilities::COMM_VIEW);return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('tasks');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND assigned_employee_id=%d FOR UPDATE",$id,$a->companyId,$a->employeeId),ARRAY_A);if(!$r)throw new DomainException('Task not found.','task_not_found',404);if((string)$r['status']!=='open')throw new DomainException('Only open tasks can be completed.','task_state_invalid',409);Db::mustUpdate($db,$t,['status'=>'completed','completed_at'=>Db::now()],['id'=>$id]);Audit::add($a,'task.complete','task',$id,[]);return['id'=>$id,'status'=>'completed'];});}
}
